        return [row[:] for row in grid]

    # Match columns containing the same non-barrier color both above and below it.
    above = {}
    below = {}
    for r in range(barrier):
        for c, v in enumerate(grid[r]):
            if v:
                above.setdefault(v, set()).add(c)
    for r in range(barrier + 1, h):
        for c, v in enumerate(grid[r]):
            if v and v != grid[barrier][0]:
                below.setdefault(v, set()).add(c)

    out = [row[:] for row in grid]
    for color, cols_above in above.items():
        for c in cols_above & below.get(color, set()):
            for r in range(1, barrier):
                if out[r][c] == 0:
